  ],
  "attack_progression": [
    {"step": 1, "tactic": "Credential Access — Steal Web Session Cookie", "technique": "T1539", "what_happened": "At 2026-05-11 02:14:09 UTC, Suricata logged HTTP requests to data.dstip=10.108.57.10 (the Citrix/NetScaler gateway) carrying NetScaler session cookies (NSC_AAAC / NSC_TASS format) in the Cookie header, originating from data.srcip=91.108.56.22 with data.http.user_agent='Citrix Receiver/19.12.0.40 Win'. The exact same NSC_AAAC token value had been observed earlier (2026-05-10 17:42-18:55 UTC) bound to data.srcip=203.0.113.45 — the legitimate session-origin IP. A session token valid for one IP suddenly being replayed from a completely different IP and geography, with no intervening /cgi/login authentication event, is the canonical T1539 stolen-web-session-cookie signal. data.url values touched: /vpn/index.html, /citrix/sessions, /Citrix/StoreWeb/auth/about, /logon/LogonPoint/index.html.", "chain_reason": "Suricata HTTP alerts with data.srcip=91.108.56.22 + Cookie header containing an NSC_AAAC value that was previously bound to a DIFFERENT data.srcip (203.0.113.45). Same token, two source IPs, two geographies, ~7h apart, no login event in between = session token replay.", "first_seen": "2026-05-11T02:14:09+0000"},
    {"step": 2, "tactic": "Defense Evasion / Initial Access — NetScaler AAAD Authentication Bypass", "technique": "T1133", "what_happened": "At ~02:19 UTC the same data.srcip=91.108.56.22 sent HTTP POST requests carrying the stolen NSC_AAAC / NSC_TASS cookies to NetScaler authentication endpoints: data.url=/cgi/login and data.url=/vpn/../vpns/portal/scripts/logincheck.pl. The /cgi/login POST with a pre-existing session cookie and an empty passwd field is the NetScaler AAAD authentication-bypass pattern — the attacker is trying to get the gateway to accept the replayed session as already-authenticated WITHOUT presenting credentials. The path '/vpn/../vpns/portal/scripts/logincheck.pl' is a directory-traversal-style access to the NetScaler portal login-check script, associated with known Citrix ADC/Gateway CVEs (CVE-2019-19781 path-traversal family, CVE-2023-3519 family).", "chain_reason": "Suricata HTTP alerts: data.srcip=91.108.56.22 POSTing to data.url=/cgi/login and data.url containing '/vpns/portal/scripts/logincheck.pl' while carrying the SAME stolen NSC_AAAC cookie from step 1. Auth-endpoint POST with a pre-set session cookie and empty password = authentication bypass via replayed session.", "first_seen": "2026-05-11T02:19:33+0000"},
    {"step": 3, "tactic": "Discovery / Collection — Internal Portal Enumeration via Hijacked Session", "technique": "T1563", "what_happened": "From ~02:24 UTC the same data.srcip=91.108.56.22, still presenting the stolen NSC_AAAC cookie, issued authenticated GET requests against internal Citrix portal API endpoints: data.url=/api/portal/resources, /api/portal/applications, /api/portal/desktops, /api/portal/config, and /Citrix/StoreWeb/Resources/List. These endpoints return the published-application catalogue, virtual-desktop inventory and gateway configuration — i.e. the attacker is enumerating what the hijacked session can reach, which is the immediate pre-condition for lateral movement into the published apps and VDI desktops. The session is being actively driven from the attacker IP as if it were the legitimate user.", "chain_reason": "Suricata HTTP alerts: repeated authenticated GET from data.srcip=91.108.56.22 to data.url under /api/portal/* and /Citrix/StoreWeb/Resources/List, all carrying the same hijacked NSC_AAAC cookie. Post-bypass authenticated enumeration of the portal catalogue = remote service session hijacking actively in use (T1563).", "first_seen": "2026-05-11T02:24:02+0000"}
  ],
